/**
 * @brief Detecta una nueva pulsacion de SW1.
 * Lee el pulsador mediante polling y aplica un debounce basico.
 * Devuelve true solo ante una transicion estable liberado -> presionado.
 * @return true si se detecto una nueva pulsacion; false en caso contrario.
 */
bool HayNuevaPulsacion(void)
{
  static GPIO_PinState estado_valido = GPIO_PIN_SET; // SW1 inicialmente liberado[cite: 6]
  GPIO_PinState lectura1;
  GPIO_PinState lectura2;
  bool nueva_pulsacion = false;

  /* Primera lectura del pulsador[cite: 6] */
  lectura1 = HAL_GPIO_ReadPin(PULSADOR_GPIO_Port, PULSADOR_Pin);

  /* Solo se realiza debounce ante un posible cambio[cite: 6] */
  if (lectura1 != estado_valido) 
  {
    HAL_Delay(T_REBOTE_MS); // Bloqueo por tiempo de rebote[cite: 5, 6]
    
    /* Confirmar que el nuevo estado se mantiene[cite: 6] */
    lectura2 = HAL_GPIO_ReadPin(PULSADOR_GPIO_Port, PULSADOR_Pin);
    
    if (lectura2 == lectura1) 
    {
      GPIO_PinState estado_anterior = estado_valido;
      estado_valido = lectura2;

      /* SW1 es activo en bajo: SET -> RESET indica pulsacion[cite: 4, 6] */
      if ((estado_anterior == GPIO_PIN_SET) && (estado_valido == GPIO_PIN_RESET)) 
      {
        nueva_pulsacion = true;
      }
    }
  }

  return nueva_pulsacion;
}
